sp_widget.client_script:
function($rootScope,$scope,spModal,spUtil) {	
	var c = this;
	// Use a position indicator to know which record to update
	c.discPos = 0; 
	c.display = false;
	c.createNew = false;

	c.displayButton = function() {
		if (c.createNew == true){
			c.createNew = false; 
			c.data.newCount = ''; 		
			c.data.newPrice = '';
		}   
		if (c.display == false){
			c.display = true; 
		} else {
			if (c.display == true){
				c.display = false; 
			} 
		}
	}

	c.createButton = function() {	
		if (c.display == true){
			c.display = false;		 
		}  		 
		//c.createNew = true;
		if (c.createNew == false){			 
			c.createNew = true; 

		} else {
			if (c.createNew == true){
				c.createNew = false; 
			} 
		}
	}

	c.selectItem = function(idx) {		
		// Set the position indicator to the index value passed in on select
		c.discPos = idx;

		var id = c.data.bmwDiscs[idx].sys_id;
	//	console.log('Disc  ID je : ' + id);
		$rootScope.discID = id;	 
		$rootScope.$emit('selectDisc', 	id);	 
	}	

	$rootScope.$on('updateDisc', function(event,data){	 
		c.data.bmwDiscs[c.discPos].u_price = data.u_price;
		c.data.bmwDiscs[c.discPos].u_count = data.u_count;
		c.data.bmwDiscs[c.discPos].u_priceallpcs = data.u_priceallpcs;
	});

	$rootScope.$on('deleteDisc', function(event,data){
		c.data.bmwDiscs.splice(c.discPos,1);		
	}); 

	c.displayNewModellParamDisc = function(){ //https://www.servicenow.com/community/now-platform-forum/how-to-pull-the-current-value-of-a-dropdown-box-in-a-ui-page/m-p/1073555
		var myBox = document.getElementById('newModell');
		var selIndex = myBox.selectedIndex;
		var selOptions = myBox.options;
		//var index = selOptions[selIndex].index; 	var myValueModell = selOptions[selIndex].value;
		var textc = selOptions[selIndex].text;	
		c.data.newModell = textc;		 
	}

	c.displayNewCreatedParamDisc = function(){
		console.log('JD, z disc create   c.data.newMark  je: ' + c.data.newMark); 	console.log('JD, z disc create   c.data.newModell  je: ' +  c.data.newModell);	 
		console.log('JD, z disc create   c.data.newPerformance  je: ' + c.data.newPerformance); 		console.log('JD, z disc create   c.data.newCount  je: ' + c.data.newCount); 		
		console.log('JD, z disc create   c.data.newPrice  je: ' + c.data.newPrice);		console.log('---- ');
	}

	c.createNewDiscRecord = function(){
		c.server.get({
			action: 'createDisc',
			discMark: c.data.newMark,
			discModell: c.data.newModell,
			discPerformance: c.data.newPerformance,
			discCount: c.data.newCount,
			discPrice: c.data.newPrice
		}).then(function(r){
			c.data.bmwDiscs.unshift(r.data.newDisc);
			c.data.discID = r.data.discID;
			$rootScope.discID = c.data.discID;
			$rootScope.$emit('selectDisc', c.data.discID);

		});
		c.data.newMark = ''; 
		c.data.newModell = '';
		c.data.newPerformance = '';
		c.data.newCount = ''; 		
		c.data.newPrice = '';
	} 

	$scope.modells = {	 // https://codepen.io/nitinz/pen/bwmzQe // https://codepen.io/nitinz/pen/ozmvqE // https://codepen.io/nitinz/pen/bwmzQe

		'31 (2019 - 2024)': ['1 1.6  (56 kW)', '2 1.9 TDi ( 62 kW )','3 2.3 TDi (80 kW)'],
		'32 Coupe (2014 - 2021)': ['4 1.6 JTDM ( 110 kW )', '5 JTDM ( 130 kW )', '6 JDM (95 kW)']
	}

	$scope.mark = ['BMW'];
	$scope.prices = ['15', '20','25', '30','35', '40','45', '50'];
	$scope.counts = ['4', '8','12', '16','20']; 
}

sp_widget.css:
input[type="text"].ng-invalid,
input[type="password"].ng-invalid,
input[type="date"].ng-invalid,
input[type="number"].ng-invalid,
select.ng-invalid{
    border-left: 5px solid #ff0000;
    background-color: #FFEBD6;
}

input[type="text"].ng-valid,
input[type="password"].ng-valid,
input[type="date"].ng-valid,
input[type="number"].ng-valid,
select.ng-valid{
    background-color: #FFFFFF;
    border-left: 5px solid #088b0b;
}

input[type="text"]:disabled.ng-valid{
    background-color: #efefef;
    border: 1px solid #ccc;
}

sp_widget.script:
(function() {
	/* populate the 'data' object */
	/* e.g., data.table = $sp.getValue('table'); */

	data.bmwDiscs = [];
	var bmwDiscsGR = new GlideRecord('x_1461179_disk_sho_disc_bmw_admin');	 
	bmwDiscsGR.orderByDesc('sys_created_on');	
	bmwDiscsGR.query();	 

	while(bmwDiscsGR.next()){
		var discObj = {};
		$sp.getRecordDisplayValues(discObj,bmwDiscsGR,'u_mark, u_modell, u_performance,	u_count, u_price, u_priceallpcs, sys_id');
		data.bmwDiscs.push(discObj);
	}

	if(input){
		if(input.action == 'createDisc'){
			var newDiscs = new GlideRecord('x_1461179_disk_sho_disc_bmw_admin');
			newDiscs.newRecord();		 

			newDiscs.u_mark = input.discMark;
			newDiscs.u_modell = input.discModell;
			newDiscs.u_performance = input.discPerformance;		
			var count = input.discCount;
			newDiscs.u_count = count;
			var price = input.discPrice;
			newDiscs.u_price = price;
			newDiscs.u_priceallpcs = (parseInt(count) * parseInt(price));
			newDiscs.u_created = new GlideDateTime();
			//newDiscs.update();			
			console.log('JD, z disc createDisc newDiscs.getValue (u_performance)  je: ' +  newDiscs.getValue('u_performance'));
			var id = newDiscs.insert();			
			data.discID = id;
		 	data.newDisc = {};
		 	$sp.getRecordDisplayValues(data.newDisc, newDiscs,'sys_id, u_mark, u_modell, u_performance, u_count, u_price, u_priceallpcs, u_created');			 
		}
	}

})();
